import{_ as n,I as i,c as s,o as a,a3 as r,b as l,w as t,a as c,J as d,a4 as h}from"./chunks/framework.BusRvirq.js";const I=JSON.parse('{"title":"엔터프라이즈 도입 FAQ 및 프라이빗 AI 보안","description":"SyncVerse 도입을 검토 중인 엔터프라이즈 고객을 위한 자주 묻는 질문(FAQ), 사내 폐쇄망 온프레미스 프라이빗 AI 구축 방안, 기존 CI/CD 및 Git 시스템 연동 가이드입니다.","frontmatter":{"title":"엔터프라이즈 도입 FAQ 및 프라이빗 AI 보안","sidebarTitle":"도입 FAQ","description":"SyncVerse 도입을 검토 중인 엔터프라이즈 고객을 위한 자주 묻는 질문(FAQ), 사내 폐쇄망 온프레미스 프라이빗 AI 구축 방안, 기존 CI/CD 및 Git 시스템 연동 가이드입니다.","head":[["meta",{"name":"keywords","content":"SyncVerse, Enterprise FAQ, 온프레미스, 프라이빗 AI, 폐쇄망, Ollama, vLLM, Git 연동, Jenkins 연동, Kubernetes"}],["meta",{"property":"og:title","content":"SyncVerse: 엔터프라이즈 도입 FAQ 및 프라이빗 AI 보안"}],["meta",{"property":"og:description","content":"사내 온프레미스 구축부터 기존 시스템 연동까지 엔터프라이즈 도입 핵심 FAQ"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/syncverse/enterprise-faq.html"}]],"sort":10},"headers":[],"relativePath":"syncverse/enterprise-faq.md","filePath":"ko/syncverse/enterprise-faq.md","lastUpdated":1787442384000}'),p={name:"syncverse/enterprise-faq.md"};function A(C,e,b,m,_,g){const o=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=r('<h1 id="엔터프라이즈-도입-faq-및-프라이빗-ai-보안" tabindex="-1">엔터프라이즈 도입 FAQ 및 프라이빗 AI 보안 <a class="header-anchor" href="#엔터프라이즈-도입-faq-및-프라이빗-ai-보안" aria-label="Permalink to “엔터프라이즈 도입 FAQ 및 프라이빗 AI 보안”">​</a></h1><p>SyncVerse를 실제 기업 환경에 도입하기 위해 고객사 아키텍트와 보안 담당자가 자주 문의하는 질문과 기술적 답변을 정리했습니다.</p><hr><h2 id="_1-보안-및-프라이빗-ai-환경" tabindex="-1">1. 보안 및 프라이빗 AI 환경 <a class="header-anchor" href="#_1-보안-및-프라이빗-ai-환경" aria-label="Permalink to “1. 보안 및 프라이빗 AI 환경”">​</a></h2><h3 id="q1-사내-소스코드와-데이터가-외부-ai-벤더-openai-등-로-전송되지-않도록-구성할-수-있나요" tabindex="-1">Q1. 사내 소스코드와 데이터가 외부 AI 벤더(OpenAI 등)로 전송되지 않도록 구성할 수 있나요? <a class="header-anchor" href="#q1-사내-소스코드와-데이터가-외부-ai-벤더-openai-등-로-전송되지-않도록-구성할-수-있나요" aria-label="Permalink to “Q1. 사내 소스코드와 데이터가 외부 AI 벤더(OpenAI 등)로 전송되지 않도록 구성할 수 있나요?”">​</a></h3><blockquote><p><strong>A. 사내 폐쇄망(Air-Gapped) 및 온프레미스 구성이 가능합니다.</strong><br> SyncVerse는 사내에 구축된 오픈소스 LLM(vLLM, Ollama, 사내 파인튜닝된 Llama 3 / Qwen 등) 및 사내 GPU 서버와의 연동을 지원합니다. 또한 상용 클라우드 LLM을 사용하는 경우에도 <strong>PII 자동 마스킹 필터</strong>와 <strong>엔터프라이즈 전용 데이터 미학습(Zero Data Retention) 엔드포인트</strong>를 통해 데이터를 안전하게 보호합니다.</p></blockquote><h3 id="q2-ai가-실수로-상용-데이터베이스를-손상시킬-위험은-없나요" tabindex="-1">Q2. AI가 실수로 상용 데이터베이스를 손상시킬 위험은 없나요? <a class="header-anchor" href="#q2-ai가-실수로-상용-데이터베이스를-손상시킬-위험은-없나요" aria-label="Permalink to “Q2. AI가 실수로 상용 데이터베이스를 손상시킬 위험은 없나요?”">​</a></h3><blockquote><p><strong>A. HITL(Human-In-The-Loop) 거버넌스로 사전에 차단됩니다.</strong><br><code>ALTER TABLE</code>, <code>DROP</code> 등 모든 스키마 변경 DDL과 상용(Production) 배포는 에이전트 단독으로 실행할 수 없으며, 시스템 아키텍트의 명시적 승인 및 2FA 인증을 거쳐야만 실행됩니다.</p></blockquote><hr><h2 id="_2-기존-인프라-및-시스템-연동" tabindex="-1">2. 기존 인프라 및 시스템 연동 <a class="header-anchor" href="#_2-기존-인프라-및-시스템-연동" aria-label="Permalink to “2. 기존 인프라 및 시스템 연동”">​</a></h2><h3 id="q3-현재-사용-중인-git-ci-cd-사내-메신저와-연동할-수-있나요" tabindex="-1">Q3. 현재 사용 중인 Git, CI/CD, 사내 메신저와 연동할 수 있나요? <a class="header-anchor" href="#q3-현재-사용-중인-git-ci-cd-사내-메신저와-연동할-수-있나요" aria-label="Permalink to “Q3. 현재 사용 중인 Git, CI/CD, 사내 메신저와 연동할 수 있나요?”">​</a></h3><blockquote><p><strong>A. 표준 엔터프라이즈 인프라와의 연동 인터페이스를 제공합니다.</strong></p><ul><li><strong>형상관리</strong>: GitHub, GitLab, Bitbucket (작업 브랜치 생성, PR 발행, 코드 Diff 대조)</li><li><strong>CI/CD 파이프라인</strong>: Jenkins, GitHub Actions, GitLab CI, ArgoCD</li><li><strong>컨테이너 오케스트레이션</strong>: Kubernetes, Docker Compose</li><li><strong>협업 도구</strong>: Slack, Microsoft Teams, Jira, Dooray (승인 요청 알림 및 상태 조회)</li></ul></blockquote>',12)),(a(),l(h,null,{default:t(()=>[d(o,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Git%5B%22Git%20%2F%20GitLab%5Cn(PR%20%26%20Diff)%22%5D%20%3C--%3E%20Verse%5B%22SyncVerse%20%EA%B4%80%EC%A0%9C%ED%83%91%22%5D%0A%20%20%20%20CI%5B%22Jenkins%20%2F%20K8s%5Cn(%EB%B9%8C%EB%93%9C%20%26%20%EB%B0%B0%ED%8F%AC)%22%5D%20%3C--%3E%20Verse%0A%20%20%20%20Slack%5B%22Slack%20%2F%20Teams%5Cn(%EC%8A%B9%EC%9D%B8%20%EC%95%8C%EB%A6%BC)%22%5D%20%3C--%3E%20Verse%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h3 id="q4-java-spring-boot-외에-다른-언어로-개발된-레거시-시스템도-지원하나요" tabindex="-1">Q4. Java Spring Boot 외에 다른 언어로 개발된 레거시 시스템도 지원하나요? <a class="header-anchor" href="#q4-java-spring-boot-외에-다른-언어로-개발된-레거시-시스템도-지원하나요" aria-label="Permalink to “Q4. Java Spring Boot 외에 다른 언어로 개발된 레거시 시스템도 지원하나요?”">​</a></h3><blockquote><p><strong>A. 네, 지원합니다.</strong><br> SyncVerse는 표준 <strong>Model Context Protocol (MCP)</strong>과 <strong>REST/JSON-RPC</strong> 통신을 사용하므로, Python(FastAPI), Node.js(NestJS), Go, C# 등 어떤 언어로 작성된 마이크로서비스라도 표준 MCP Server 래퍼를 연결하면 관제탑에 편입할 수 있습니다.</p></blockquote><hr><h2 id="_3-도입-절차-및-poc-로드맵" tabindex="-1">3. 도입 절차 및 PoC 로드맵 <a class="header-anchor" href="#_3-도입-절차-및-poc-로드맵" aria-label="Permalink to “3. 도입 절차 및 PoC 로드맵”">​</a></h2><h3 id="_1단계-준비-및-poc-2주-4주" tabindex="-1">1단계: 준비 및 PoC (2주 ~ 4주) <a class="header-anchor" href="#_1단계-준비-및-poc-2주-4주" aria-label="Permalink to “1단계: 준비 및 PoC (2주 ~ 4주)”">​</a></h3><ul><li>대상 도메인 서비스 1개를 선정하여 SyncVerse 관제탑 연동</li><li>대상 서비스 Git 저장소 및 SyncBoot, SyncCMS, SyncETA 에이전트 MCP 등록</li><li>인텐트 라우팅 정확도 및 자연어 지시 수행 테스트</li></ul><h3 id="_2단계-시범-운영-4주-8주" tabindex="-1">2단계: 시범 운영 (4주 ~ 8주) <a class="header-anchor" href="#_2단계-시범-운영-4주-8주" aria-label="Permalink to “2단계: 시범 운영 (4주 ~ 8주)”">​</a></h3><ul><li>개발/스테이징(Dev/Stage) 환경에서 무인 QA 및 자가치유 파이프라인 가동</li><li>아키텍트 HITL 승인 콘솔 적용 및 기능 배포 리드타임(TTM) 단축 측정</li></ul><h3 id="_3단계-전사-ai-dlc-생태계-확산-이후" tabindex="-1">3단계: 전사 AI DLC 생태계 확산 (이후) <a class="header-anchor" href="#_3단계-전사-ai-dlc-생태계-확산-이후" aria-label="Permalink to “3단계: 전사 AI DLC 생태계 확산 (이후)”">​</a></h3><ul><li>전사 마이크로서비스로 관제탑 확대 적용</li><li>SyncInsight 연동을 통한 비즈니스 데이터-개발 실행 연동</li></ul><hr><h2 id="_4-라이선스-및-기술-지원" tabindex="-1">4. 라이선스 및 기술 지원 <a class="header-anchor" href="#_4-라이선스-및-기술-지원" aria-label="Permalink to “4. 라이선스 및 기술 지원”">​</a></h2><p>SyncVerse는 오픈소스 커뮤니티 에디션과 기업용 엔터프라이즈 에디션을 제공합니다.</p><ul><li><strong>도입 문의 및 PoC 지원</strong>: <code>contact@empasy.com</code></li><li><strong>공식 기술 지원 포털</strong>: <a href="https://doc.empasy.com" target="_blank" rel="noreferrer">https://doc.empasy.com</a></li></ul>',14))])}const k=n(p,[["render",A]]);export{I as __pageData,k as default};
